module coin_optimizer (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] P,\n    input wire [7:0] N1,\n    input wire [7:0] N5,\n    input wire [7:0] N10,\n    input wire [7:0] N25,\n    output reg [7:0] result,\n    output reg valid,\n    output reg done\n);\n    localparam [3:0] IDLE = 4'b0000;\n    localparam [3:0] CHECK_X25 = 4'b0010;\n    localparam [3:0] CHECK_X10 = 4'b0100;\n    localparam [3:0] CHECK_X5 = 4'b0110;\n    localparam [3:0] DONE = 4'b1011;\n    reg [3:0] state;\n    reg [3:0] x25;\n    reg [4:0] x10;\n    reg [5:0] x5;\n    reg [7:0] max_coins;\n    reg found;\n    wire [15:0] val25 = x25 * 8'd25;\n    wire [15:0] val10 = x10 * 8'd10;\n    wire [15:0] val5  = x5 * 8'd5;\n    wire [15:0] total = val25 + val10 + val5;\n    wire [7:0] x1 = P - total[7:0];\n    wire total_le_P = (total <= P);\n    wire x1_le_N1 = (x1 <= N1);\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 8'd0;\n            valid <= 1'b0;\n            done <= 1'b0;\n            x25 <= 4'd0;\n            x10 <= 5'd0;\n            x5 <= 6'd0;\n            max_coins <= 8'd0;\n            found <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        x25 <= 4'd0;\n                        x10 <= 5'd0;\n                        x5 <= 6'd0;\n                        max_coins <= 8'd0;\n                        found <= 1'b0;\n                        state <= CHECK_X25;\n                    end\n                end\n                CHECK_X25: begin\n                    if (x25 <= N25 && val25 <= P) begin\n                        x10 <= 5'd0;\n                        state <= CHECK_X10;\n                    end else begin\n                        state <= DONE;\n                    end\n                end\n                CHECK_X10: begin\n                    if (x10 <= N10 && (val25 + val10) <= P) begin\n                        x5 <= 6'd0;\n                        state <= CHECK_X5;\n                    end else begin\n                        if (x10 < N10) begin\n                            x10 <= x10 + 5'd1;\n                            state <= CHECK_X10;\n                        end else begin\n                            x25 <= x25 + 4'd1;\n                            state <= CHECK_X25;\n                        end\n                    end\n                end\n                CHECK_X5: begin\n                    if (x5 <= N5 && total <= P) begin\n                        if (x1_le_N1) begin\n                            if (x1 + x5 + x10 + x25 > max_coins) begin\n                                max_coins <= x1 + x5 + x10 + x25;\n                                found <= 1'b1;\n                            end\n                        end\n                        if (x5 < N5) begin\n                            x5 <= x5 + 6'd1;\n                            state <= CHECK_X5;\n                        end else begin\n                            if (x10 < N10) begin\n                                x10 <= x10 + 5'd1;\n                                state <= CHECK_X10;\n                            end else begin\n                                x25 <= x25 + 4'd1;\n                                state <= CHECK_X25;\n                            end\n                        end\n                    end else begin\n                        if (x10 < N10) begin\n                            x10 <= x10 + 5'd1;\n                            state <= CHECK_X10;\n                        end else begin\n                            x25 <= x25 + 4'd1;\n                            state <= CHECK_X25;\n                        end\n                    end\n                end\n                DONE: begin\n                    result <= max_coins;\n                    valid <= found;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule